/**
 * Build-time compilation of the lesson-schema validator (#2205).
 *
 * `ajv.compile()` at runtime generates the validator via `new Function` -
 * an `unsafe-eval` CSP violation that broke /content under the fixed
 * policy. Ajv supports standalone code generation instead: this script
 * compiles the pinned schema mirror ONCE and writes a plain-function
 * module; the bundle then contains zero runtime code generation.
 *
 * Coupling to the schema pin: the generated file embeds the sha256 of the
 * schema source it was built from. A re-pin without regeneration is caught
 * by the drift test (lesson-schema-validator.standalone.test.ts), never
 * silent. Regenerated by `bun run generate:validator` (wired into
 * `make sync-schema`).
 */
import {createHash} from "node:crypto";
import {readFileSync, writeFileSync} from "node:fs";
import {dirname, join} from "node:path";
import {fileURLToPath} from "node:url";

import Ajv2020 from "ajv/dist/2020.js";
import standaloneCode from "ajv/dist/standalone/index.js";
import addFormats from "ajv-formats";
import {_} from "ajv/dist/compile/codegen/index.js";

const here = dirname(fileURLToPath(import.meta.url));
const schemaPath = join(here, "../src/lib/content/validation/lesson.schema.generated.json");
const outPath = join(here, "../src/lib/content/validation/lesson-schema-validator.standalone.cjs");

const schemaText = readFileSync(schemaPath, "utf-8");
const schemaHash = createHash("sha256").update(schemaText).digest("hex");
const schema = JSON.parse(schemaText);

const ajv = new Ajv2020.default({
    allErrors: true,
    strict: false,
    code: {source: true, formats: _`require("ajv-formats/dist/formats").fullFormats`},
});
addFormats.default(ajv);
const validate = ajv.compile(schema);
const moduleCode = standaloneCode.default(ajv, validate);

const banner = `/* GENERATED by scripts/generate-lesson-validator.mjs - DO NOT EDIT.
 * Standalone (build-time-compiled) lesson-schema validator: no runtime
 * code generation, hence CSP-clean (#2205).
 * schema-source-sha256: ${schemaHash}
 * Regenerate: bun run generate:validator (runs inside make sync-schema).
 */
`;
writeFileSync(outPath, banner + moduleCode + "\n", "utf-8");
console.log(`written ${outPath}`);
console.log(`schema sha256 ${schemaHash}`);
